/// Creates a contract using the caller's client and signing configuration.
let bind (web3: Web3) (address: string) = web3.Eth.GetContract(abi, address)

/// Encodes amendOrder(bytes32,uint256,uint256,uint8) without RPC.
let encodeAmendOrder (contract: Contract) (args: AmendOrderParams) =
    contract.GetFunctionBySignature("0x21b0939f").GetData([| box args.OrderId; box args.NewPrice; box args.NewAmount; box args.NewFlags |])

let decodeAmendOrderResult (data: string) : AmendOrderResult =
    Nethereum.ABI.FunctionEncoding.FunctionCallDecoder().DecodeFunctionOutput(Activator.CreateInstance<AmendOrderResult>(), data)

/// Sends through the client's configured transaction manager.
let sendAmendOrder (contract: Contract) (options: TransactionInput) (args: AmendOrderParams) =
    if isNull options then nullArg "options"
    if not (isNull options.Value) && options.Value.Value <> BigInteger.Zero then invalidArg "options" "Function is not payable"
    options.To <- contract.Address
    contract.GetFunctionBySignature("0x21b0939f").SendTransactionAsync(options, [| box args.OrderId; box args.NewPrice; box args.NewAmount; box args.NewFlags |])

