let filterBatchAuctionCleared (contract: Contract) (fromBlock: BlockParameter) (toBlock: BlockParameter) =
    let filter = contract.GetEventBySignature("0x23282c934e72938479026cddeea9b09391eaeb609937a76d3b01a1d5292231d8").CreateFilterInput(fromBlock, toBlock)
    filter

let decodeBatchAuctionClearedEvent (contract: Contract) (log: FilterLog) : BatchAuctionClearedEvent =
    let decoded = contract.GetEventBySignature("0x23282c934e72938479026cddeea9b09391eaeb609937a76d3b01a1d5292231d8").DecodeAllEventsForEvent<BatchAuctionClearedEvent>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryBatchAuctionCleared (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<BatchAuctionClearedEvent>>()
        let event = contract.GetEventBySignature("0x23282c934e72938479026cddeea9b09391eaeb609937a76d3b01a1d5292231d8")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<BatchAuctionClearedEvent>(decodeBatchAuctionClearedEvent contract log, log))
        return result
    }

